// services/user/getHomeData.js
import { doc, getDoc } from "firebase/firestore";
import { db } from "../../firebaseConfig"; // Уверете се, че пътят е правилен

export async function getHomeData() {
    try {
        // Прочитане на документа "welcomeUser" в колекцията "homePage"
        const docRef = doc(db, "homePage", "welcomeUser");
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
            return docSnap.data(); // Връща данните като обект
        } else {
            console.error("No such document in Firestore!");
            return null;
        }
    } catch (error) {
        console.error("Error fetching data from Firestore:", error);
        throw error;
    }
}
